-- =====================================================================================================================================
-- V6 module tables: GENERATED by backend/api/tools/gen-module-tables.mjs from the CommunityOS field definitions - edit the generator, not this file.
-- One real table per object (113 tables). Standard columns, typed fields, foreign keys between objects; RLS, audit stamping and
-- grants are attached to every tenant table in V9. Select options are validated by the API (config.field_definition), not by CHECKs.
-- =====================================================================================================================================

-- tickets (Maintenance)
CREATE TABLE IF NOT EXISTS maintenance.ticket (
  community_id uuid        NOT NULL REFERENCES platform.community (id),
  id           uuid        NOT NULL DEFAULT gen_random_uuid(),
  short_id     text,
  ticket_number text,
  task_type    text,
  title        text,
  description  text,
  unit_id      uuid,
  category     text,
  sub_category text,
  priority     text,
  status       text,
  assigned_to  text,
  sla_due_at   timestamptz,
  preferred_time text,
  scope        text,
  location     text,
  affected_units text[] NOT NULL DEFAULT '{}',
  has_photos   boolean NOT NULL DEFAULT false,
  wish_id      uuid,
  asset_id     uuid,
  asset_name   text,
  asset_ref    text,
  source       text,
  awaiting_parts boolean NOT NULL DEFAULT false,
  materials_cost numeric(14,2),
  financial    boolean NOT NULL DEFAULT false,
  quotation_status text,
  selected_quotation_id uuid,
  selected_quotation_ids uuid[] NOT NULL DEFAULT '{}',
  selected_invoice_id uuid,
  approval_stage text,
  invoice_approval_mode text,
  approved_amount numeric(14,2),
  plan         text,
  advance_ceiling numeric(14,2),
  advance_reason text,
  advance_by   text,
  advance_settled text,
  work_done    date,
  ec_approval  text,
  ec_approved_by_id uuid,
  ec_approved_at timestamptz,
  final_required boolean NOT NULL DEFAULT false,
  treasurer_approval text,
  treasurer_approved_by_id uuid,
  treasurer_approved_at timestamptz,
  invoice_status text,
  payment_status text,
  attachments  jsonb NOT NULL DEFAULT '[]',
  resident_rating numeric,
  raised_by_id uuid,
  raised_by_role_id uuid,
  custom       jsonb       NOT NULL DEFAULT '{}',
  version      bigint      NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   uuid,
  updated_at   timestamptz NOT NULL DEFAULT now(),
  updated_by   uuid,
  PRIMARY KEY (community_id, id),
  UNIQUE (community_id, short_id)
);
CREATE INDEX IF NOT EXISTS maintenance_ticket_recent ON maintenance.ticket (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS maintenance_ticket_status ON maintenance.ticket (community_id, status);

